/* macOS-inspired chrome and motion. All controls act on this portfolio. */
(() => {
const media=matchMedia('(prefers-reduced-motion: reduce)'),motions=new WeakMap(),live=new Set();
const enabled=()=>!media.matches&&!document.body.classList.contains('reduce-motion')&&!document.hidden;
function cancel(el){const a=motions.get(el);if(a){a.cancel();live.delete(a);motions.delete(el)}el.classList.remove('mac-closing')}
function play(el,frames,options={}){cancel(el);if(!enabled()||!el.animate)return null;const a=el.animate(frames,{duration:480,easing:'cubic-bezier(.18,.82,.24,1)',...options});motions.set(el,a);live.add(a);a.finished.then(()=>{live.delete(a);if(motions.get(el)===a)motions.delete(el)},()=>live.delete(a));return a}
function openWindow(el,source){const to=el.getBoundingClientRect(),from=source?.getBoundingClientRect?.()||{left:innerWidth/2,top:innerHeight*.85,width:0,height:0};const x=(from.left+from.width/2-to.left-to.width/2)*.5,y=(from.top+from.height/2-to.top-to.height/2)*.7;return play(el,[{opacity:0,transform:`translate(${x}px,${y}px) scale(.72,.74)`,filter:'blur(3px)',borderRadius:'24px'},{opacity:1,transform:'translate(0,-2px) scale(1.008)',filter:'blur(0)',borderRadius:'14px',offset:.78},{opacity:1,transform:'translate(0,0) scale(1)',filter:'blur(0)',borderRadius:'14px'}],{duration:560})}
function minimise(el,dock){const r=el.getBoundingClientRect(),d=dock.getBoundingClientRect(),x=d.left+d.width/2-r.left-r.width/2,y=d.top+d.height/2-r.top-r.height/2;const a=play(el,[{opacity:1,transform:el.style.transform||'translate(0,0)',clipPath:'polygon(0 0,100% 0,100% 100%,0 100%)',filter:'blur(0)'},{opacity:1,transform:`translate(${x*.1}px,${y*.12}px) scale(.92,.95)`,clipPath:'polygon(0 0,100% 0,82% 100%,18% 100%)',offset:.27},{opacity:1,transform:`translate(${x*.55}px,${y*.57}px) scale(.43,.5)`,clipPath:'polygon(0 0,100% 0,66% 100%,34% 100%)',offset:.62},{opacity:.35,transform:`translate(${x}px,${y}px) scale(${Math.max(.025,d.width/r.width)},.018)`,clipPath:'polygon(0 0,100% 0,100% 100%,0 100%)',filter:'blur(1px)'}],{duration:620,easing:'cubic-bezier(.36,.02,.35,1)',fill:'forwards'});el.classList.add('mac-closing');return a}
function dismiss(el){const a=play(el,[{opacity:1,scale:'1',filter:'blur(0)'},{opacity:0,scale:'.96',filter:'blur(2px)'}],{duration:180,easing:'ease-out',fill:'forwards'});el.classList.add('mac-closing');return a}
function closeWindow(el,dock,minimised,done){if(el.classList.contains('mac-closing'))return;if(!enabled()){cancel(el);done();return}const a=minimised?minimise(el,dock):dismiss(el);if(!a){done();return}a.finished.then(()=>{done();a.cancel();el.classList.remove('mac-closing')},()=>{});}
window.MacDesktopMotion={open:openWindow,minimise,dismiss,close:closeWindow,cancel,enabled};
const apple=document.querySelector('.wordmark'),menubar=document.querySelector('.menubar'),appName=menubar.querySelector(':scope > strong');apple.classList.remove('profile-wordmark');apple.classList.add('apple-wordmark');apple.removeAttribute('data-open');apple.setAttribute('aria-label','Apple menu');apple.setAttribute('aria-haspopup','menu');apple.setAttribute('aria-expanded','false');apple.innerHTML='<img src="assets/macos/apple.svg" alt="" draggable="false">';appName.textContent='Finder';
menubar.querySelector('nav').innerHTML=['File','Edit','View','Window','Help'].map(name=>`<button data-mac-menu="${name.toLowerCase()}" aria-haspopup="menu" aria-expanded="false">${name}</button>`).join('');
const menu=document.createElement('div');menu.className='mac-system-menu';menu.hidden=true;menu.setAttribute('role','menu');document.body.append(menu);let origin=null;
const item=(title,action,shortcut='')=>`<button role="menuitem" data-mac-action="${action}"><span>${title}</span><small>${shortcut}</small></button>`,line='<hr role="separator">';
const menus={apple:()=>item('About This Portfolio','about')+line+item('Appearance…','appearance')+item('Open Safari','safari')+item('Game Collection','games')+line+item('Lock Screen','lock'),file:()=>item('Open Portfolio','about')+item('Selected Work','work')+item('Services & CV Help','services')+item('New Safari Tab','new-tab')+line+item('Close Window','close','Esc'),edit:()=>item('Search Portfolio…','search','⌘ K')+item('Find a Page in Safari…','safari')+line+item('Contact & Enquiries','contact'),view:()=>item('Day, Night & Auto…','appearance')+item('Maximise / Restore Window','maximise')+line+item('Reset Folder Layout','reset-layout'),window:()=>item('Finder','files')+item('Safari','safari')+item('Games','games')+line+item('Minimise Window','minimise'),help:()=>item('Explore This Portfolio','help')+item('About Princewill','about')+item('Work With Me','contact')};
function closeMenu(focus=false){menu.hidden=true;origin?.setAttribute('aria-expanded','false');if(focus)origin?.focus();origin=null}
function showMenu(button,name){if(!isUnlocked)return;const same=origin===button&&!menu.hidden;closeMenu();if(same)return;origin=button;origin.setAttribute('aria-expanded','true');menu.innerHTML=menus[name]();menu.hidden=false;menu.setAttribute('aria-label',name==='apple'?'Apple menu':name+' menu');const box=button.getBoundingClientRect();menu.style.left=Math.max(6,Math.min(innerWidth-235,box.left-5))+'px';menu.style.top=box.bottom+5+'px';play(menu,[{opacity:0,scale:'.965',translate:'0 -4px'},{opacity:1,scale:'1',translate:'0 0'}],{duration:170,easing:'cubic-bezier(.2,.75,.3,1)'});menu.querySelector('button')?.focus()}
apple.onclick=()=>showMenu(apple,'apple');menubar.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-mac-menu]');if(b)showMenu(b,b.dataset.macMenu)});
menubar.addEventListener('pointerover',e=>{if(menu.hidden)return;const b=e.target.closest('[data-mac-menu],.apple-wordmark');if(b&&b!==origin)showMenu(b,b.dataset.macMenu||'apple')});
function act(action){const sf=document.querySelector('#portfolio-safari');closeMenu();if(action==='appearance'){window.PortfolioAppearance?.openOptions();return}if(action==='lock'){document.querySelector('#lock-button').click();return}if(action==='reset-layout'){document.querySelector('.desktop-layout-reset')?.click();return}if(action==='search'){openSearch();return}if(action==='help'){notify('Click folders to explore. Drag to move them. Use Safari to search your pages. The dock brings everything together.');return}if(['close','minimise','maximise'].includes(action)){if(sf?.open&&appName.textContent==='Safari'){sf.querySelector('#safari-'+(action==='close'?'close':action)).click()}else if(finder.open)document.querySelector('#window-'+action).click();return}if(action==='new-tab'){window.openSafari();document.querySelector('#safari-add').click();return}openView(action)}
menu.addEventListener('click',e=>{const b=e.target.closest('[data-mac-action]');if(b)act(b.dataset.macAction)});menu.addEventListener('keydown',e=>{const options=[...menu.querySelectorAll('[role=menuitem]')],i=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();options[e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length].focus()}if(e.key==='Escape'){e.preventDefault();closeMenu(true)}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const buttons=[apple,...menubar.querySelectorAll('[data-mac-menu]')],next=buttons[(buttons.indexOf(origin)+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];showMenu(next,next.dataset.macMenu||'apple')}if(e.key==='Tab')closeMenu()});
document.addEventListener('click',e=>{if(!menu.contains(e.target)&&!e.target.closest('[data-mac-menu],.apple-wordmark'))closeMenu()});window.addEventListener('blur',()=>closeMenu());window.addEventListener('resize',()=>closeMenu());
// Dialogs in the top layer need their own native-feeling entrances.
for(const selector of ['#spotlight','.desktop-trash-window']){const el=document.querySelector(selector);if(el)new MutationObserver(()=>{if(el.open)play(el,[{opacity:0,scale:'.96',translate:'0 -8px',filter:'blur(2px)'},{opacity:1,scale:'1',translate:'0 0',filter:'blur(0)'}],{duration:260})}).observe(el,{attributes:true,attributeFilter:['open']})}
const safari=document.querySelector('#portfolio-safari');
const desktop=document.querySelector('#desktop');desktop.append(finder);if(safari)desktop.append(safari);
function raise(el){finder.style.zIndex=el===finder?'62':'61';if(safari)safari.style.zIndex=el===safari?'62':'61';appName.textContent=el===safari?'Safari':'Finder'}
for(const el of [finder,safari].filter(Boolean)){el.addEventListener('pointerdown',()=>raise(el));el.addEventListener('close',()=>{cancel(el);appName.textContent=safari?.open?'Safari':'Finder'});new MutationObserver(()=>{if(el.open)raise(el);else appName.textContent=safari?.open?'Safari':'Finder'}).observe(el,{attributes:true,attributeFilter:['open']});}
finder.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeFinder()}});

window.addEventListener('portfolio:desktop-window',e=>raise(e.detail.app==='safari'?safari:finder));
function stop(){for(const a of live)a.finish();live.clear();closeMenu()}
media.addEventListener('change',()=>{if(media.matches)stop()});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);
})();
